<h2>OPD per tahun</h2><p class="muted">Nama OPD disimpan per tahun agar perubahan nama tidak mengubah riwayat tahun sebelumnya.</p><div class="panel table-wrap"><table><thead><tr><th>OPD</th><th>Tahun</th><th>Nama pada tahun</th><th>Aktif</th></tr></thead><tbody><?php foreach($opds as $o)foreach($snapshots as $ot)if($ot['id_opd_pemkab']==$o['id_opd_pemkab']): ?><tr><td><?= $esc($o['nama_opd']) ?></td><td><?= $ot['tahun'] ?></td><td><?= $esc($ot['nama_opd']) ?></td><td><?= $ot['status_aktif']==='Y'?'Ya':'Tidak' ?></td></tr><?php endif; ?></tbody></table></div>
<?php if($actor['role']==='admin'): ?><form class="panel grid" method="post" action="<?= $url('save/opd') ?>"><?= $token ?><label>OPD<select name="id"><option value="0">+ OPD baru</option><?php foreach($opds as $o): ?><option value="<?= $o['id_opd_pemkab'] ?>"><?= $esc($o['nama_opd']) ?></option><?php endforeach; ?></select></label><label>Tahun<input required type="number" min="2000" max="2100" name="tahun" value="<?= date('Y') ?>"></label><label>Nama OPD pada tahun<input required name="nama_opd" maxlength="180"></label><label>Status tahun<select name="status_aktif"><option value="Y">Aktif</option><option value="N">Nonaktif</option></select></label><button>Simpan OPD / tahun</button></form><?php endif; ?>
